'use client';

import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useEffect, useMemo, useState } from 'react';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';

type DayOfWeek = 'Monday' | 'Tuesday' | 'Wednesday' | 'Thursday' | 'Friday' | 'Saturday';

interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data: T;
  errors?: Record<string, string[]>;
}

interface Section {
  id: number;
  courseCode: string;
  courseTitle: string;
  sectionName: string;
  dayOfWeek: DayOfWeek;
  timeStart: string; // HH:mm:ss
  timeEnd: string;   // HH:mm:ss
  expectedStudents: number;
}

interface RoomApi {
  id: number;
  room_number: string;
  building: string;
  capacity: number;
  is_available: boolean;
  type?: { id: number; name: string };
}

interface RoomsPayload {
  data: RoomApi[];
}

// Fallback until instructor sections endpoint exists
const LOCAL_SECTIONS: Section[] = [
  { id: 1, courseCode: 'CS 3101', courseTitle: 'Data Structures and Algorithms', sectionName: 'BSCS 3-A', dayOfWeek: 'Monday', timeStart: '07:30:00', timeEnd: '09:00:00', expectedStudents: 38 },
  { id: 2, courseCode: 'CS 4101', courseTitle: 'Software Engineering', sectionName: 'BSCS 4-A', dayOfWeek: 'Tuesday', timeStart: '13:00:00', timeEnd: '14:30:00', expectedStudents: 25 },
];

export default function CreateRequestPage() {
  const router = useRouter();
  const [sections] = useState<Section[]>(LOCAL_SECTIONS);
  const [selectedSectionId, setSelectedSectionId] = useState<number | null>(null);
  const [rooms, setRooms] = useState<RoomApi[]>([]);
  const [selectedRoomId, setSelectedRoomId] = useState<number | null>(null);
  const [loadingRooms, setLoadingRooms] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  const section = useMemo(() => sections.find((s) => s.id === selectedSectionId) ?? null, [sections, selectedSectionId]);
  const room = useMemo(() => rooms.find((r) => r.id === selectedRoomId) ?? null, [rooms, selectedRoomId]);

  useEffect(() => {
    async function loadRooms() {
      if (!section) {
        setRooms([]);
        setSelectedRoomId(null);
        return;
      }
      setLoadingRooms(true);
      setError('');
      try {
        const query = `/instructor/rooms?available_only=1&day=${encodeURIComponent(section.dayOfWeek)}&time_start=${encodeURIComponent(section.timeStart)}&time_end=${encodeURIComponent(section.timeEnd)}`;
        const res = await api.get<ApiEnvelope<RoomsPayload>>(query);
        setRooms(res.data?.data ?? []);
      } catch (e: unknown) {
        setRooms([]);
        setError(e instanceof Error ? e.message : 'Failed to load rooms.');
      } finally {
        setLoadingRooms(false);
      }
    }
    loadRooms();
  }, [section]);

  async function submit() {
    if (!section || !room) return;
    setSubmitting(true);
    setError('');
    setSuccess('');
    try {
      const res = await api.post<ApiEnvelope<null>>('/requests', {
        section_id: section.id,
        room_id: room.id,
        day_of_week: section.dayOfWeek,
        time_start: section.timeStart,
        time_end: section.timeEnd,
      });
      if (!res.success) {
        throw new Error(res.errors?.request?.[0] || res.message || 'Failed to submit request.');
      }
      setSuccess(res.message || 'Request submitted.');
      setTimeout(() => router.push('/requests'), 900);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to submit request.');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <AppShell role="instructor" userName="Instructor" pageTitle="Create Request">
      <div className="max-w-2xl mx-auto">
        <div className="flex items-center gap-3 mb-5">
          <Link href="/requests" className="btn btn-ghost">Back</Link>
          <h1 className="text-[18px] font-semibold">Submit Room Request</h1>
        </div>

        <div className="card card-body flex flex-col gap-4">
          {error && <div className="text-sm" style={{ color: 'var(--color-error)' }}>{error}</div>}
          {success && <div className="text-sm" style={{ color: 'var(--color-success)' }}>{success}</div>}

          <div className="form-group">
            <label className="form-label" htmlFor="section">Section</label>
            <select id="section" value={selectedSectionId ?? ''} onChange={(e) => setSelectedSectionId(e.target.value ? Number(e.target.value) : null)}>
              <option value="">Select section</option>
              {sections.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.courseCode} - {s.sectionName} ({s.dayOfWeek} {s.timeStart.slice(0, 5)}-{s.timeEnd.slice(0, 5)})
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="room">Room</label>
            <select id="room" value={selectedRoomId ?? ''} onChange={(e) => setSelectedRoomId(e.target.value ? Number(e.target.value) : null)} disabled={!section || loadingRooms}>
              <option value="">{loadingRooms ? 'Loading rooms...' : 'Select room'}</option>
              {rooms.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.room_number} - {r.building} ({r.capacity}) {r.type?.name ? `- ${r.type.name}` : ''}
                </option>
              ))}
            </select>
          </div>

          {section && room && (
            <div className="text-xs" style={{ color: 'var(--color-text-muted)' }}>
              Expected students: {section.expectedStudents}, room capacity: {room.capacity}
            </div>
          )}

          <button className="btn btn-primary" disabled={!section || !room || submitting} onClick={submit}>
            {submitting ? 'Submitting...' : 'Submit Request'}
          </button>
        </div>
      </div>
    </AppShell>
  );
}
